style.css:
@-moz-document domain("ead.senaibahia.com.br") {
/* Plano de fundo principal */
  body, .main-inner, .dashboard-card, .region-main, #region-main {
    background-color: #121212 !important;
    color: #E0E0E0 !important;
  }

  /* Navegação lateral */
  .drawer, .drawer .list-group-item {
    background-color: #1E1E1E !important;
    color: #CCCCCC !important;
  }

  /* Cabeçalho */
  .navbar, .navbar-light, .header, .page-header {
    background-color: #1A1A1A !important;
    color: #F0F0F0 !important;
  }

  /* Links */
  a, .activityinstance > a {
    color: #80CBC4 !important;
  }

  /* Botões */
  .btn, input[type="submit"], .btn-primary {
    background-color: #2E2E2E !important;
    color: #FFFFFF !important;
    border: none !important;
  }

  /* Títulos */
  h1, h2, h3, h4, h5 {
    color: #FAFAFA !important;
  }

  /* Blocos e cartões */
  .card, .block, .activity {
    background-color: #1B1B1B !important;
    color: #DDDDDD !important;
    border-color: #2C2C2C !important;
  }

  /* Inputs e campos */
  input, textarea, select {
    background-color: #2A2A2A !important;
    color: #FFFFFF !important;
    border: 1px solid #444 !important;
  }

  /* Interações */
  .btn:hover, a:hover {
    background-color: #333 !important;
    color: #A5D6A7 !important;
  }

  /* Novos elementos solicitados */
  .format-tiles .course-content ul li.section.main:not(.delegated-section),
  .activity-item {
    background-color: #6f6f6f2b !important;
  }
}
